package org.example.spotifymixer.runtime;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.text.*;import java.lang.ref.*;import java.util.*;
/** Bounded, reversible Android-view styling; Compose/custom drawn rows are intentionally untouched. */
final class ViewTweaks implements ViewTreeObserver.OnGlobalLayoutListener,Runnable {
 private final WeakReference<View> root;private final SharedPreferences prefs;private final Handler handler=new Handler(Looper.getMainLooper());private final Map<View,Saved> saved=new WeakHashMap<>();private final ViewTreeObserver observer;private boolean queued,closed;private String signature="";
 private static final class Saved {int max,lines,minimum,height,top,bottom,left,right;android.text.TextUtils.TruncateAt ellipsize;boolean text,row,horizontal;int lastHeight,lastMinimum,lastTop,lastBottom;}
 ViewTweaks(Activity a){View r=a.getWindow().getDecorView();root=new WeakReference<>(r);prefs=a.getSharedPreferences(Mixer.PREFS,0);observer=r.getViewTreeObserver();observer.addOnGlobalLayoutListener(this);}
 public void onGlobalLayout(){if((prefs.getBoolean("compact_enabled",false)||prefs.getBoolean("track_info_enabled",false))&&!queued){queued=true;handler.postDelayed(this,500);}}
 void refresh(){handler.removeCallbacks(this);queued=false;run();}
 public void run(){queued=false;if(closed)return;View r=root.get();if(r==null)return;boolean compact=prefs.getBoolean("compact_enabled",false),info=prefs.getBoolean("track_info_enabled",false);String title=MediaToolsRuntime.title(),artist=MediaToolsRuntime.artist();String next=compact+"|"+info+"|"+title+"|"+artist;if(!next.equals(signature)){restore();signature=next;}if(!compact&&!info)return;
  ArrayDeque<View> todo=new ArrayDeque<>();todo.add(r);int count=0;
  while(!todo.isEmpty()&&count++<2000){View v=todo.remove();
   if(info&&!saved.containsKey(v)&&v instanceof TextView&&!(v instanceof Button)&&!(v instanceof EditText)){TextView t=(TextView)v;String value=t.getText().toString();if((!title.equals("No current track")&&value.equals(title))||(!artist.isEmpty()&&value.equals(artist))){Saved s=new Saved();s.text=true;s.max=t.getMaxLines();s.lines=t.getMinLines();s.ellipsize=t.getEllipsize();s.horizontal=Build.VERSION.SDK_INT>=29?t.isHorizontallyScrollable():s.max==1;saved.put(t,s);t.setSingleLine(false);t.setMaxLines(3);t.setEllipsize(TextUtils.TruncateAt.END);}}
   if(compact&&v instanceof ViewGroup&&v.getClass().getName().contains("RecyclerView")){ViewGroup list=(ViewGroup)v;int floor=(int)(48*v.getResources().getDisplayMetrics().density+.5f);for(int i=0;i<list.getChildCount();i++){View row=list.getChildAt(i);if(saved.containsKey(row))continue;ViewGroup.LayoutParams lp=row.getLayoutParams();if(lp==null)continue;Saved s=saved.get(row);if(s==null)s=new Saved();s.row=true;s.height=lp.height;s.minimum=row.getMinimumHeight();s.left=row.getPaddingLeft();s.right=row.getPaddingRight();s.top=row.getPaddingTop();s.bottom=row.getPaddingBottom();saved.put(row,s);if(lp.height>floor){lp.height=Math.max(floor,(int)(lp.height*.8f));row.setLayoutParams(lp);}row.setMinimumHeight(Math.max(floor,Math.min(s.minimum,floor)));row.setPadding(s.left,s.top/2,s.right,s.bottom/2);s.lastHeight=lp.height;s.lastMinimum=row.getMinimumHeight();s.lastTop=s.top/2;s.lastBottom=s.bottom/2;}}
   if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)todo.add(g.getChildAt(i));}
  }
 }
 private void restore(){for(Map.Entry<View,Saved> e:new ArrayList<>(saved.entrySet())){View v=e.getKey();Saved s=e.getValue();if(v==null)continue;if(s.text&&v instanceof TextView){TextView t=(TextView)v;if(t.getMaxLines()==3&&t.getEllipsize()==TextUtils.TruncateAt.END){t.setHorizontallyScrolling(s.horizontal);t.setMaxLines(s.max);t.setMinLines(s.lines);t.setEllipsize(s.ellipsize);}}if(s.row){ViewGroup.LayoutParams lp=v.getLayoutParams();if(lp!=null&&lp.height==s.lastHeight&&s.height!=lp.height){lp.height=s.height;v.setLayoutParams(lp);}if(v.getMinimumHeight()==s.lastMinimum)v.setMinimumHeight(s.minimum);if(v.getPaddingTop()==s.lastTop&&v.getPaddingBottom()==s.lastBottom&&v.getPaddingLeft()==s.left&&v.getPaddingRight()==s.right)v.setPadding(s.left,s.top,s.right,s.bottom);}}saved.clear();}
 void close(){closed=true;handler.removeCallbacks(this);if(observer.isAlive())observer.removeOnGlobalLayoutListener(this);restore();}
}
